			want:  map[string]int{"go": 4},
		},
		{
			name:  "punctuation stripped",
			input: "Hello, world! Hello... world?",
			want:  map[string]int{"hello": 2, "world": 2},
		},
		{
			name:  "repeated words",
			input: "test test TEST Test tESt",
			want:  map[string]int{"test": 5},
