    // when transition ends, snap to final position without animation
    setTimeout(()=>{
      strip.style.transition = 'none';
      const finalOffset = (finalIdx[i] % state.symbols.length) * symbolHeight;
      strip.style.transform = `translateY(-${finalOffset}px)`;
    }, durations[i]);
  });

  // after all reels stopped, evaluate win
  const maxDur = Math.max(...durations);
  setTimeout(()=>{
    state.spinning = false;
    const winInfo = checkWin(state.result);
    handleOutcome(winInfo);
    updateUI();
  }, maxDur+100); // little buffer
}

/* ---------- Win Evaluation ---------- */
function checkWin(symbols){
  const [a,b,c] = symbols;
  // map combination strings to rows
  const combos = [
    {cond: a==="7️⃣" && b==="7️⃣" && c==="7️⃣", mul:100, name:"JACKPOT!", row:"row-100"},
    {cond: a==="⭐" && b==="⭐" && c==="⭐", mul:50, name:"THREE STARS", row:"row-50"},
    {cond: a==="🔔" && b==="🔔" && c==="🔔", mul:20, name:"THREE BELLS", row:"row-20"},
    {cond: a==="🍇" && b==="🍇" && c==="🍇", mul:15, name:"THREE GRAPES", row:"row-15"},
    {cond: a==="🍊" && b==="🍊" && c==="🍊", mul:10, name:"THREE ORANGES", row:"row-10"},
    {cond: a==="🍋" && b==="🍋" && c==="🍋", mul:5,  name:"THREE LEMONS", row:"row-5"},
    {cond: a==="🍒" && b==="🍒" && c==="🍒", mul:3,  name:"THREE CHERRIES", row:"row-3"},
    {cond: a==="🍒" && b==="🍒",               mul:2,  name:"DOUBLE CHERRY", row:"row-2"},
    {cond:true,                              mul:0,  name:"", row:"row-0"}
  ];
  return combos.find(c=>c.cond);
}

/* ---------- Outcome Handling ---------- */
function handleOutcome(winInfo){
  const msgEl = $('#msg');
  const {multiplier, name, row}=winInfo;
  const win = multiplier>0;
  // highlight pay‑table row
  $(`#${row}`).classList.add('highlight');

  if(win){
    // flash symbols on the reels
    state.reelElements.forEach(obj=>obj.reel.classList.add('flash'));
    setTimeout(()=>state.reelElements.forEach(obj=>obj.reel.classList.remove('flash')), 1200);
    // calculate win amount
    const winAmt = state.bet * multiplier;
    const oldCred = state.credits;
    state.credits += winAmt;
    // show win text
    msgEl.textContent = `${name} +${winAmt} credits!`;
    // animate credit count up
    updateCreditsDisplay(oldCred, state.credits);
  }else{
    // shake on loss
    $('#reelContainer').classList.add('shake');
    setTimeout(()=>$('#reelContainer').classList.remove('shake'),600);
    msgEl.textContent = 'No win…';
  }

  // check for game‑over
  if(state.credits===0){
    setTimeout(showOverlay,800);
  }
}

/* ---------- Game Over Overlay ---------- */
function showOverlay(){
  $('#overlay').style.display='flex';
}
function hideOverlay(){
  $('#overlay').style.display='none';
}

/* ---------- Initialise Game ---------- */
initState();
</script>
</body>
</html>
```

### How it works
| Feature | Implementation |
|---------|----------------|
| **Reels** | Three `<div class="reel">` each with a scrolling `<div class="reel-strip">`. Symbols are plain emojis. |
| **Spin animation** | CSS `transform: translateY` with a `transition` timed per reel (800 ms, 1200 ms, 1600 ms). Random extra cycles give the illusion of continuous spin. |
| **Betting** | Buttons (`data-bet`) set `state.bet`. Credits start at 100, bet deducted before spin, winnings added after.
